refentry.refsect1:
  &reftitle.examples;

   Exemplo de Time\Duration::compare


<?php
$oneSecond = \Time\Duration::fromSeconds(1);
$oneAndAHalfSeconds = \Time\Duration::fromMilliseconds(1500);
$billionNanoseconds = \Time\Duration::fromNanoseconds(1_000_000_000);

var_dump(\Time\Duration::compare($oneSecond, $oneAndAHalfSeconds) < 0);
var_dump(\Time\Duration::compare($oneAndAHalfSeconds, $oneSecond) > 0);
var_dump(\Time\Duration::compare($oneSecond, $billionNanoseconds) === 0);

// Durações negativas são menores que as positivas.
var_dump(\Time\Duration::compare($oneSecond->negate(), $oneSecond) < 0);


   &example.outputs;


bool(true)
bool(true)
bool(true)
bool(true)




   Ordenando durações com Time\Duration::compare


<?php
$durations = [
    \Time\Duration::fromMinutes(2),
    \Time\Duration::fromMilliseconds(250),
    \Time\Duration::fromSeconds(5),
];

usort($durations, \Time\Duration::compare(...));

foreach ($durations as $duration) {
    printf("%d.%09d\n", $duration->seconds, $duration->nanoseconds);
}


   &example.outputs;


0.250000000
5.000000000
120.000000000
